using UnityEngine;using UnityEditor;using System.IO;using System.Linq;using System.Collections.Generic;using Object=UnityEngine.Object;
public static class SeolpyeongFaceDiagnostics{
 const string R="LocalArchive/SeolpyeongFace20261019";static Material trial;
 static Transform Model()=>Object.FindObjectsByType<Transform>(FindObjectsInactive.Include).Single(t=>t.name=="Seolpyeong"&&t.Find("VarcoVisual")).Find("VarcoVisual/Model");
 [MenuItem("Tools/RedCliffs/Seolpyeong Face/Probe Eyes")]public static void Probe(){var model=Model();var renderer=model.GetComponent<Renderer>();var mesh=model.GetComponent<MeshFilter>().sharedMesh;var material=renderer.sharedMaterials[1];var texture=material.GetTexture("_BaseMap");var report=new List<string>{"Shader="+material.shader.name,"Texture="+AssetDatabase.GetAssetPath(texture),"PropertyBlock="+renderer.HasPropertyBlock(),"TextureFormat="+((Texture2D)texture).format,"NormalsNonFinite="+mesh.normals.Count(v=>float.IsNaN(v.x)||float.IsNaN(v.y)||float.IsNaN(v.z)||float.IsInfinity(v.x)||float.IsInfinity(v.y)||float.IsInfinity(v.z)),"UVNonFinite="+mesh.uv.Count(v=>float.IsNaN(v.x)||float.IsNaN(v.y)),"Keywords="+string.Join(",",material.shaderKeywords)};var rt=RenderTexture.GetTemporary(512,512,0);var old=RenderTexture.active;Graphics.Blit(texture,rt);RenderTexture.active=rt;var copy=new Texture2D(512,512,TextureFormat.RGBA32,false);copy.ReadPixels(new Rect(0,0,512,512),0,0);copy.Apply();report.Add("GPU color center="+copy.GetPixel(128,256));File.WriteAllBytes(R+"/gpu-eye-texture.png",copy.EncodeToPNG());RenderTexture.active=old;RenderTexture.ReleaseTemporary(rt);Object.DestroyImmediate(copy);var mo=model.parent.GetComponent<RedCliffMystery.VarcoIdleMotion>();if(EditorApplication.isPlaying){mo.StartSpeech(null,0);mo.Sample(.07f);var rest=mesh.vertices;mo.StartSpeech("아",0);mo.Sample(.07f);var sp=mesh.vertices;var moved=rest.Select((v,i)=>new{v,i}).Where(x=>(x.v-sp[x.i]).sqrMagnitude>1e-12f).Select(x=>model.parent.InverseTransformPoint(model.TransformPoint(x.v)).y).ToArray();report.Add("Speech moved="+moved.Length+" y="+(moved.Length>0?moved.Min()+".."+moved.Max():"none"));mo.StartSpeech(null,0);mo.Sample(Time.time);}File.WriteAllLines(R+"/eye-diagnostic.txt",report);}
 [MenuItem("Tools/RedCliffs/Seolpyeong Face/Trial Unlit Eyes")]public static void Trial(){if(!EditorApplication.isPlaying)throw new System.Exception("Play only");var r=Model().GetComponent<Renderer>();var a=r.sharedMaterials;trial=new Material(Shader.Find("Universal Render Pipeline/Unlit")){hideFlags=HideFlags.HideAndDontSave};trial.SetTexture("_BaseMap",a[1].GetTexture("_BaseMap"));trial.SetColor("_BaseColor",Color.white);trial.SetFloat("_AlphaClip",1);trial.SetFloat("_Cutoff",.45f);trial.EnableKeyword("_ALPHATEST_ON");a[1]=trial;r.sharedMaterials=a;}
 [MenuItem("Tools/RedCliffs/Seolpyeong Face/Restore Eye Material")]public static void Restore(){var r=Model().GetComponent<Renderer>();var a=r.sharedMaterials;a[1]=AssetDatabase.LoadAssetAtPath<Material>("Assets/Art/Characters/SeolpyeongFace20261019/Eyes.mat");r.sharedMaterials=a;if(trial)Object.DestroyImmediate(trial);}
